"use client";
import { conversationLocalStorage as localStorage, conversationSessionStorage as sessionStorage } from "../../lib/recovery-session";

import { startIndependentRecovery, checkRecoveryAdmission } from "../../lib/recovery-session";
import { temporaryStateMessage } from "../../lib/temporary-state-error";

import { maintenanceMessage } from "../../lib/maintenance-result";

import { TEMPORARY_STATE_KEY, DEVICE_USER_KEY } from "../../lib/device-conversation";
import {
  useEffect,
  useState,
} from "react";

import {
  supabase,
} from "../../lib/supabase";

import {
  registerPushSubscription,
  sendTestPushNotification,
} from "../../lib/push-notifications";

type ChatMessage = {
  role: "misaki" | "user";
  text: string;
  requestId?: string;
};

type DailyUsage = {
  date: string;
  count: number;
};

type MisakiTodayMemory = {
  date: string;
  items: string[];
};

type Plan =
  | "free"
  | "premium";

type UsageRpcResult = {
  message_count?: number;
  remaining?: number;
  is_premium?: boolean;
};

type ApiUsage = {
  messageCount?: number;
  remaining?: number;
  isPremium?: boolean;
};

const STORAGE_KEY =
  "misaki-chat-history";

const MEMORY_KEY =
  "misaki-long-term-memory";

const RELATIONSHIP_KEY =
  "misaki-relationship-points";

const MISAKI_TODAY_MEMORY_KEY =
  "misaki-today-memory";

const MAX_MESSAGES = 60;

// 無料版は1日20往復まで
const FREE_DAILY_LIMIT = 20;

const INITIAL_MESSAGES:
  ChatMessage[] = [];



function getJapanDateKey() {
  return new Date()
    .toLocaleDateString(
      "ja-JP",
      {
        timeZone:
          "Asia/Tokyo",

        year:
          "numeric",

        month:
          "2-digit",

        day:
          "2-digit",
      }
    );
}

function getJapanCurrentTime() {
  return new Date()
    .toLocaleString(
      "ja-JP",
      {
        timeZone:
          "Asia/Tokyo",

        year:
          "numeric",

        month:
          "2-digit",

        day:
          "2-digit",

        weekday:
          "short",

        hour:
          "2-digit",

        minute:
          "2-digit",

        hour12:
          false,
      }
    );
}

function createEmptyTodayMemory():
  MisakiTodayMemory {
  return {
    date:
      getJapanDateKey(),

    items: [],
  };
}

function isPremiumActive(
  plan:
    | string
    | null
    | undefined,

  premiumUntil:
    | string
    | null
    | undefined
) {
  if (
    plan !==
    "premium"
  ) {
    return false;
  }

  if (
    !premiumUntil
  ) {
    return true;
  }

  const expiresAt =
    new Date(
      premiumUntil
    ).getTime();

  if (
    !Number.isFinite(
      expiresAt
    )
  ) {
    return false;
  }

  return (
    expiresAt >
    Date.now()
  );
}

function getFirstRpcRow<T>(
  value: unknown
): T | null {
  if (
    Array.isArray(
      value
    ) &&
    value.length >
      0
  ) {
    return value[0] as T;
  }

  if (
    value &&
    typeof value ===
      "object"
  ) {
    return value as T;
  }

  return null;
}

export default function ChatPage() {
  const [historyDiagnostics, setHistoryDiagnostics] = useState<Record<string, number> | null>(null);
  const [showHistoryDiagnostics, setShowHistoryDiagnostics] = useState(false);
  const [recoveryCode, setRecoveryCode] = useState<string | null>(null);
  const [recoveryStarting, setRecoveryStarting] = useState(false);
  const [recoveryOwner, setRecoveryOwner] = useState<string | null>(null);
  async function openRecovery(code: string, owner: string, active: () => boolean) {
    const { data, error } = await supabase.auth.getSession();
    if (!active() || error || !data.session?.user.is_anonymous || data.session.user.id !== owner) return;
    if (!await checkRecoveryAdmission(fetch)) {
      if (active()) setSendError("今は新しい会話を始められません。少し待ってからもう一度開いてね。");
      return;
    }
    const { data: current, error: currentError } = await supabase.auth.getSession();
    if (!active() || currentError || !current.session?.user.is_anonymous || current.session.user.id !== owner) return;
    startIndependentRecovery(current.session.user, code, crypto.randomUUID());
    window.location.assign('/chat');
  }
  async function beginIndependentConversation() {
    if (recoveryStarting || !recoveryCode || !recoveryOwner) return;
    if (!window.confirm("古い状態を保全したまま、このタブで独立した新しい会話を始めます。古い会話や記憶は引き継ぎません。よろしいですか？")) return;
    setRecoveryStarting(true);
    try {
      await openRecovery(recoveryCode, recoveryOwner, () => true);
    } catch {
      setSendError("新しい会話を開始できませんでした。既存データは変更していません。");
    } finally {
      setRecoveryStarting(false);
    }
  }

  const [
    message,
    setMessage,
  ] =
    useState("");

  const [
    messages,
    setMessages,
  ] =
    useState<
      ChatMessage[]
    >(
      INITIAL_MESSAGES
    );

  const [replyFeedback, setReplyFeedback] = useState<Record<string, { rating: "good" | "bad"; reason?: string }>>({});

  const [
    memory,
    setMemory,
  ] =
    useState<
      string[]
    >([]);

  const [
    misakiTodayMemory,
    setMisakiTodayMemory,
  ] =
    useState<
      MisakiTodayMemory
    >(
      createEmptyTodayMemory()
    );

  const [
    relationshipPoints,
    setRelationshipPoints,
  ] =
    useState(0);

  const [
    dailyUsage,
    setDailyUsage,
  ] =
    useState<
      DailyUsage
    >({
      date:
        getJapanDateKey(),

      count:
        0,
    });

  const [
    plan,
    setPlan,
  ] =
    useState<
      Plan
    >(
      "free"
    );

  const [
    accountLoaded,
    setAccountLoaded,
  ] =
    useState(
      false
    );

  const [
    showPremium,
    setShowPremium,
  ] =
    useState(
      false
    );

  const [
    showMemory,
    setShowMemory,
  ] =
    useState(
      false
    );

  const [
    showMenu,
    setShowMenu,
  ] =
    useState(
      false
    );

  useEffect(() => {
    if (recoveryCode !== "TEMPORARY_STATE_EXPIRED" || !recoveryOwner || showMenu) return;
    let active = true;
    const timer = window.setTimeout(() => {
      void openRecovery(recoveryCode, recoveryOwner, () => active).catch(() => {
        if (active) setSendError("新しい会話を開始できませんでした。もう一度開いてね。");
      });
    }, 5000);
    return () => {
      active = false;
      window.clearTimeout(timer);
    };
  }, [recoveryCode, recoveryOwner, showMenu]);

  const [
    loading,
    setLoading,
  ] =
    useState(
      false
    );

  const [
    waitingOnReply,
    setWaitingOnReply,
  ] =
    useState(
      false
    );

  const [
    sendError,
    setSendError,
  ] =
    useState(
      ""
    );

  const [hasPriorHistory, setHasPriorHistory] = useState<boolean | null>(null);
  const [historyLoading, setHistoryLoading] = useState(true);

  const [
    loaded,
    setLoaded,
  ] =
    useState(
      false
    );

  const [
    notificationPermission,
    setNotificationPermission,
  ] =
    useState<
      | "default"
      | "granted"
      | "denied"
      | "unsupported"
    >(
      "default"
    );

  const isPremium =
    plan ===
    "premium";

  const today =
    getJapanDateKey();

  const usageCountToday =
    dailyUsage.date ===
    today
      ? dailyUsage.count
      : 0;

  const freeRemaining =
    Math.max(
      0,
      FREE_DAILY_LIMIT -
        usageCountToday
    );

  const freeLimitReached =
    accountLoaded &&
    !isPremium &&
    usageCountToday >=
      FREE_DAILY_LIMIT;

  useEffect(
    () => {
      let active =
        true;

      async function loadEntitlement(
        userId:
          string
      ) {
        for (
          let attempt =
            0;
          attempt <
            5;
          attempt +=
            1
        ) {
          const {
            data,
            error,
          } =
            await supabase
              .from(
                "user_entitlements"
              )
              .select(
                "plan,premium_until"
              )
              .eq(
                "user_id",
                userId
              )
              .maybeSingle();

          if (
            error
          ) {
            throw error;
          }

          if (
            data
          ) {
            return isPremiumActive(
              data.plan,
              data.premium_until
            );
          }

          await new Promise(
            (
              resolve
            ) =>
              window.setTimeout(
                resolve,
                350
              )
          );
        }

        return false;
      }

      async function loadDailyUsage() {
        const {
          data,
          error,
        } =
          await supabase.rpc(
            "get_daily_message_usage"
          );

        if (
          error
        ) {
          throw error;
        }

        const usage =
          getFirstRpcRow<
            UsageRpcResult
          >(
            data
          );

        return {
          count:
            typeof usage
              ?.message_count ===
              "number"
              ? Math.max(
                  0,
                  Math.floor(
                    usage
                      .message_count
                  )
                )
              : 0,

          isPremium:
            usage
              ?.is_premium ===
            true,
        };
      }

      async function initializeAccount() {
        try {
          const {
            data:
              sessionData,
            error:
              sessionError,
          } =
            await supabase
              .auth
              .getSession();

          if (
            sessionError
          ) {
            throw sessionError;
          }

          let user =
            sessionData
              .session
              ?.user ??
            null;

          if (
            !user
          ) {
            const {
              data:
                signInData,
              error:
                signInError,
            } =
              await supabase
                .auth
                .signInAnonymously();

            if (
              signInError
            ) {
              throw signInError;
            }

            user =
              signInData
                .user ??
              null;
          }

          if (
            !user
          ) {
            throw new Error(
              "Supabase user was not created."
            );
          }

          const [
            entitlementPremium,
            usage,
          ] =
            await Promise
              .all([
                loadEntitlement(
                  user.id
                ),

                loadDailyUsage(),
              ]);

          if (
            !active
          ) {
            return;
          }

          const premium =
            entitlementPremium ||
            usage
              .isPremium;

          setPlan(
            premium
              ? "premium"
              : "free"
          );

          setDailyUsage({
            date:
              getJapanDateKey(),

            count:
              usage.count,
          });
        } catch (
          error
        ) {
          console.error(
            "Supabase account initialization failed:",
            error
          );

          if (
            active
          ) {
            setPlan(
              "free"
            );

            setDailyUsage({
              date:
                getJapanDateKey(),

              count:
                0,
            });
          }
        } finally {
          if (
            active
          ) {
            setAccountLoaded(
              true
            );
          }
        }
      }

      initializeAccount();

      return () => {
        active =
          false;
      };
    },
    []
  );

  useEffect(
    () => {
      if (
        !accountLoaded
      ) {
        return;
      }

      if (
        isPremium
      ) {
        setShowPremium(
          false
        );

        return;
      }

      if (
        usageCountToday >=
        FREE_DAILY_LIMIT
      ) {
        setShowPremium(
          true
        );
      }
    },
    [
      accountLoaded,
      isPremium,
      usageCountToday,
    ]
  );

  useEffect(
    () => {
      if (
        "serviceWorker" in
        navigator
      ) {
        navigator
          .serviceWorker
          .register(
            "/sw.js"
          )
          .then(
            (
              registration
            ) => {
              console.log(
                "Service Worker registered:",
                registration
              );
            }
          )
          .catch(
            (
              error
            ) => {
              console.error(
                "Service Worker registration failed:",
                error
              );
            }
          );
      }
    },
    []
  );

  useEffect(
    () => {
      if (
        !(
          "Notification" in
          window
        )
      ) {
        setNotificationPermission(
          "unsupported"
        );

        return;
      }

      setNotificationPermission(
        Notification
          .permission
      );
    },
    []
  );

  useEffect(() => {
    let active = true;
    function applyRoot(state: any) {
      if (!active || !state) return;
      if (Array.isArray(state.memory)) setMemory(state.memory);
      if (typeof state.relationshipPoints === "number") setRelationshipPoints(state.relationshipPoints);
      if (state.misakiTodayMemory) applyTodayMemory(state.misakiTodayMemory);
    }
    const receive = (event: Event) => applyRoot((event as CustomEvent).detail);
    const receiveHistory = (event: Event) => {
      const history = (event as CustomEvent).detail;
      if (active && Array.isArray(history)) setMessages(history.slice(-MAX_MESSAGES));
    };
    const receiveUsage = (event: Event) => applyApiUsage((event as CustomEvent).detail);
    window.addEventListener("misaki-root-state", receive);
    window.addEventListener("misaki-history-state", receiveHistory);
    window.addEventListener("misaki-usage-state", receiveUsage);
    // Only choose the placeholder here. The server supplies all displayed messages.
    try {
      const cachedHistory = localStorage.getItem(STORAGE_KEY);
      setHasPriorHistory(Boolean((cachedHistory && cachedHistory !== "[]") || sessionStorage.getItem("misaki-pending-chat-turn")));
    } catch {
      setHasPriorHistory(true);
    }
    async function load() {
      // Enable locally with sessionStorage.setItem("misaki-history-timing", "1").
      // Timings only: never log tokens, history, user IDs or temporary state.
      const urlDiagnostics = /(?:^|[?&])historyDiagnostics=1(?:&|$)/.test(window.location?.search ?? "");
      const timingEnabled = urlDiagnostics || sessionStorage.getItem("misaki-history-timing") === "1";
      if (active) setShowHistoryDiagnostics(urlDiagnostics);
      const nowMs = () => typeof performance !== "undefined" ? performance.now() : Date.now();
      const startedAt = timingEnabled ? nowMs() : 0;
      let previousAt = startedAt;
      const timings: Record<string, number> = {};
      const checkpoint = (name: string) => {
        if (!timingEnabled) return;
        const now = nowMs();
        timings[name] = Math.round(now - previousAt);
        previousAt = now;
      };
      try {
        // A full remount ends the previous page's in-flight UI send marker.
        sessionStorage.removeItem("misaki-chat-sending");
        // Do not display unverified caches or persist an empty error-state over them.
        const accessToken = await getAccessToken();
        checkpoint("accessTokenMs");
        const expectedOwner = localStorage.getItem(DEVICE_USER_KEY);
        const response = await fetch("/api/persona/history", {
          method: "POST",
          headers: { "Content-Type": "application/json", Authorization: `Bearer ${accessToken}` },
          body: JSON.stringify({ action: "load", temporaryState: sessionStorage.getItem(TEMPORARY_STATE_KEY),
            pending: JSON.parse(sessionStorage.getItem("misaki-pending-chat-turn") || "null") }),
        });
        checkpoint("historyApiMs");
        if (timingEnabled) {
          const serverTiming = response.headers.get("Server-Timing");
          const duration = serverTiming?.match(/(?:^|,)\s*history;dur=([\d.]+)/)?.[1];
          if (duration) timings.historyServerLoadMs = Math.round(Number(duration));
          const authDuration = serverTiming?.match(/(?:^|,)\s*auth;dur=([\d.]+)/)?.[1];
          const requestDuration = serverTiming?.match(/(?:^|,)\s*request;dur=([\d.]+)/)?.[1];
          if (authDuration) timings.historyServerAuthMs = Math.round(Number(authDuration));
          if (requestDuration) timings.historyServerRequestMs = Math.round(Number(requestDuration));
        }
        if (!response.ok) {
          const result = await response.json().catch(() => null);
          if (active && temporaryStateMessage(response.status, result)) {
            setRecoveryOwner(expectedOwner);
            setRecoveryCode(result.code);
          }
          throw new Error(temporaryStateMessage(response.status, result) || maintenanceMessage(response.status, result) || "美咲の状態を読み込めませんでした。");
        }
        const state = await response.json();
        checkpoint("jsonParseMs");
        const { data: latest } = await supabase.auth.getSession();
        checkpoint("sessionVerificationMs");
        if (!active || latest.session?.user.id !== expectedOwner || localStorage.getItem(DEVICE_USER_KEY) !== expectedOwner) return;
        applyRoot(state);
        const pending = JSON.parse(sessionStorage.getItem("misaki-pending-chat-turn") || "null");
        if (state.recoveredTurn || state.history?.some((item: any) => item.requestId === pending?.requestId)) {
          sessionStorage.removeItem("misaki-pending-chat-turn");
        }
        if (typeof state.temporaryState === "string") sessionStorage.setItem(TEMPORARY_STATE_KEY, state.temporaryState);
        // Permanent history is canonical. Anonymous history remains a display cache.
        if (active && Array.isArray(state.history)) setMessages(state.history);
        for (const key of [MEMORY_KEY, RELATIONSHIP_KEY, MISAKI_TODAY_MEMORY_KEY]) localStorage.removeItem(key);
        if (active) { setRecoveryCode(null); setLoaded(true); }
        checkpoint("stateEnqueueMs");
        if (timingEnabled) {
          const summary = { ...timings, totalUntilStateEnqueueMs: Math.round(nowMs() - startedAt) };
          console.info("[misaki-history-timing]", summary);
          if (active && urlDiagnostics) setHistoryDiagnostics(summary);
        }
      } catch (error) {
        if (active) setSendError(error instanceof Error ? error.message : "状態を読み込めませんでした。");
      } finally {
        if (active) setHistoryLoading(false);
      }
    }
    void load();
    return () => {
      active = false;
      window.removeEventListener("misaki-root-state", receive);
      window.removeEventListener("misaki-history-state", receiveHistory);
      window.removeEventListener("misaki-usage-state", receiveUsage);
    };
  }, []);

  useEffect(
    () => {
      if (
        !loaded
      ) {
        return;
      }

      try {
        const limitedMessages =
          messages
            .slice(
              -MAX_MESSAGES
            );

        localStorage
          .setItem(
            STORAGE_KEY,

            JSON.stringify(
              limitedMessages
            )
          );
      } catch (
        error
      ) {
        console.error(
          "Failed to save chat history:",
          error
        );
      }
    },
    [
      messages,
      loaded,
    ]
  );

  async function getAccessToken() {
    const {
      data,
      error,
    } =
      await supabase
        .auth
        .getSession();

    if (
      error
    ) {
      throw error;
    }

    const accessToken =
      data
        .session
        ?.access_token;

    if (
      !accessToken
    ) {
      throw new Error(
        "ログイン情報を確認できませんでした。ページを再読み込みしてね。"
      );
    }

    return accessToken;
  }

  function applyApiUsage(
    value:
      unknown
  ) {
    if (
      !value ||
      typeof value !==
        "object"
    ) {
      return;
    }

    const usage =
      value as
        ApiUsage;

    if (
      usage
        .isPremium ===
      true
    ) {
      setPlan(
        "premium"
      );
    }

    if (
      typeof usage
        .messageCount ===
        "number" &&
      Number.isFinite(
        usage
          .messageCount
      )
    ) {
      setDailyUsage({
        date:
          getJapanDateKey(),

        count:
          Math.max(
            0,

            Math.floor(
              usage
                .messageCount
            )
          ),
      });
    }
  }

  async function requestNotificationPermission() {
    if (
      !(
        "Notification" in
        window
      )
    ) {
      alert(
        "この環境では通知機能を利用できません。"
      );

      setNotificationPermission(
        "unsupported"
      );

      return;
    }

    if (
      !(
        "serviceWorker" in
        navigator
      )
    ) {
      alert(
        "この環境では通知機能を利用できません。"
      );

      setNotificationPermission(
        "unsupported"
      );

      return;
    }

    if (
      !(
        "PushManager" in
        window
      )
    ) {
      alert(
        "このブラウザはPush通知に対応していません。"
      );

      setNotificationPermission(
        "unsupported"
      );

      return;
    }

    try {
      await navigator
        .serviceWorker
        .ready;

      const permission =
        await Notification
          .requestPermission();

      setNotificationPermission(
        permission
      );

      if (
        permission ===
        "denied"
      ) {
        alert(
          "通知が許可されませんでした。端末の設定から美咲の通知を許可してください。"
        );

        return;
      }

      if (
        permission !==
        "granted"
      ) {
        return;
      }

      await registerPushSubscription();

      const accessToken =
        await getAccessToken();

      try {
        await sendTestPushNotification(
          accessToken
        );

        alert(
          "通知をONにしました。今、美咲からテスト通知を送ったよ。"
        );
      } catch (
        testError
      ) {
        console.error(
          "Test push notification failed:",
          testError
        );

        alert(
          "通知端末の登録はできました。テスト通知だけ送信できませんでした。"
        );
      }
    } catch (
      error
    ) {
      console.error(
        "Push notification setup error:",
        error
      );

      const errorMessage =
        error instanceof
        Error
          ? error.message
          : "通知の設定に失敗しました。";

      alert(
        errorMessage
      );
    }
  }

  async function changeStoredState(action: string, value?: string) {
    if (loading || sessionStorage.getItem("misaki-pending-chat-turn")) throw new Error("返信を確認してから変更してください。未受信の場合は再読み込みで確認できます。");
    const accessToken = await getAccessToken();
    const { data: owner } = await supabase.auth.getSession();
    const expectedOwner = owner.session?.user.id;
    const response = await fetch("/api/persona/history", {
      method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${accessToken}` },
      body: JSON.stringify({ action, value, requestId: crypto.randomUUID(), temporaryState: sessionStorage.getItem(TEMPORARY_STATE_KEY) }),
    });
    if (!response.ok) {
      const result = await response.json().catch(() => null);
      throw new Error(temporaryStateMessage(response.status, result) || maintenanceMessage(response.status, result) || "保存できませんでした。もう一度お試しください。");
    }
    const state = await response.json();
    const { data: latest } = await supabase.auth.getSession();
    if (!expectedOwner || latest.session?.user.id !== expectedOwner || localStorage.getItem(DEVICE_USER_KEY) !== expectedOwner) throw new Error("アカウントが変更されました。");
    if (Array.isArray(state.memory)) setMemory(state.memory);
    if (typeof state.temporaryState === "string") sessionStorage.setItem(TEMPORARY_STATE_KEY, state.temporaryState);
  }
